from pathlib import Path
import base64, hashlib, subprocess, sys, zlib

root = Path(sys.argv[1]).resolve()
payload = ""
patch = zlib.decompress(base64.b64decode(payload))
expected = "a430ec638db131f24ba58f0700e14744104bff730686b508426c494b25e38b4c"
actual = hashlib.sha256(patch).hexdigest()
if actual != expected:
    raise RuntimeError(f"alpha46 patch checksum mismatch: {actual} != {expected}")

subprocess.run(["git", "-C", str(root), "apply", "--whitespace=nowarn", "-"], input=patch, check=True)
print("PKVault V8 alpha46 Apricorn icons, item-key aliases, and Poké Ball quests applied")
